"""Record the exact standalone V18 artifact after sequential native checks."""
from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parents[2];base=root/'output/elyndor/pixellab-v18'
def read(name):return json.loads((base/name).read_text(encoding='utf-8'))
a=json.loads((root/'output/elyndor/continuous-standalone-audit.json').read_text());reg=read('regression.json');revision=read('revision/report.json');campaign=read('campaign/report.json');performance=read('performance/native.json');combat=read('combat-profile-final.json');atlas=read('atlas-performance.json');voices=read('audio-audit.json');sounds=read('soundtrack-audit.json');water=read('water/report.json');locations=read('locations/report.json');macro=read('overworld/report.json')
sha=hashlib.sha256((root/'index.html').read_bytes()).hexdigest()
assert sha==reg['sha256']==a['sha256'] and a['sourceMatchesArtifact'] and not a['cropWarnings']
assert len(reg['checks'])==26 and all(q['pass']for q in reg['checks'])
assert all(q['pass']for q in [revision,atlas,voices,sounds,water,locations,macro])
assert campaign['campaign']['final']=='complete' and not campaign['errors'] and not campaign['voiceMissing']
assert not combat['newPrograms'] and combat['cpu']['p95']<25
transcripts=json.loads((root/'elyndor/audio/transcription-audit-v18.json').read_text());assert transcripts['clips']==10 and not transcripts['unresolvedWordDifferences']
r={'release':'elyndor-2026-10-28-sluice-coached-battle-current-atlas-v18','game':'The Last Light of Elyndor','artifact':{'file':'index.html','bytes':a['bytes'],'sha256':sha,'offline':True},
 'changes':['Full-width timber-and-iron sluice seals into both banks with a continuous sill and matching support frame','Carved river bathymetry and depth-clipped shores retain natural stream width; a pressure wave, world-space spray and foam travel downstream as the gate lifts','Reservoir, headrace, millrace, lower river and all cascade endpoints sample one animated hydraulic model; the river continues beyond the local scene','Two reviewed native 512-pixel PixelLab water and wet-stone materials; all water surfaces use the selected river palette','The first wildlife battle is a scripted, narrated practice sequence for target selection, Attack, timing, Soren’s MP ability, taking damage, a practice herb and Defend, followed by normal combat','Reading and the first timing window pause; practice cannot defeat the party or wildlife, consumes no net herbs, and can be skipped','Foreground buildings, trees and vegetation clear across the battle formation and restore when combat ends; the render budget preserves visibility decisions','Current published atlas version 7 supplies 22 named places, exact established landmark coordinates and seven primary roads, including the current connected volcanic geography','Fern gathering pavilion, Alderbridge shelter/care court and relief-station observation bay reserve clear ground before foliage planting; civic facilities and child locations appear in the atlas','Bridge decks and both approaches share world-space terrain material; local landscapes continue through fog with fitted background geometry'],
 'art':{'generator':'PixelLab','nativeSelectedFamilies':41,'runtimeFamilies':42,'packedSpritePoses':a['packedPoses'],'sourceCropWarnings':0,'newNativeMaterialPages':2,'materialSize':[512,512],'rejectedCandidatesExcluded':True},
 'audio':{'provider':'ElevenLabs','recordedVoices':voices['clips'],'soundAssets':sounds['sounds'],'newNarration':10,'newSoundEffects':1,'offline':True,'embeddedCredential':False,'transcription':transcripts},
 'validation':{'checks':reg['checks'],'revisionFeatures':revision,'locations':locations,'sourceMatchesArtifact':True,'storyProgressionSteps':len(campaign['campaign']['log']),'storyBattles':len(campaign['campaign']['battles']),'restoredLights':len(campaign['campaign']['restored']),'saveLoad':campaign['persistence'],'waterJoinMaxGapMetres':max(j['gap']for row in revision['water']for j in row['joins']),'overworldApproaches':macro},
 'performance':{'device':performance['device'],'nativeScenarios':performance['scenarios'],'pump':read('pump-fixed.json'),'tutorial':read('onboarding-performance.json'),'combatRenderCPU':combat['cpu'],'newCombatPrograms':len(combat['newPrograms']),'atlas':atlas,'scope':'Native Chrome on the recorded test GPU; performance varies by hardware.'}}
(root/'release.json').write_text(json.dumps(r,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print(json.dumps({'release':r['release'],'bytes':a['bytes'],'sha256':sha,'checks':len(reg['checks']),'audioAssets':voices['clips']+sounds['sounds']}))
